package pe.micaratula.app;
import android.app.Activity;
import android.os.Bundle;
import android.content.Intent;
import android.net.Uri;
import android.print.PrintManager;
import android.print.PrintAttributes;
import android.webkit.*;
import android.widget.Toast;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
public class MainActivity extends Activity {
 private WebView web; private ValueCallback<Uri[]> chooser; private String pendingBackup; private byte[] pendingPDF; private String pendingPrintMessage;
 @Override public void onCreate(Bundle b){super.onCreate(b);web=new WebView(this);setContentView(web);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(true);web.getSettings().setAllowFileAccessFromFileURLs(false);web.getSettings().setAllowUniversalAccessFromFileURLs(false);
 web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !r.getUrl().toString().startsWith("file:///android_asset/");}});
 web.setWebChromeClient(new WebChromeClient(){
 @Override public boolean onJsAlert(WebView v,String u,String msg,JsResult result){new android.app.AlertDialog.Builder(MainActivity.this).setMessage(msg).setPositiveButton("Aceptar",(d,w)->result.confirm()).setOnCancelListener(d->result.cancel()).show();return true;}
 @Override public boolean onJsConfirm(WebView v,String u,String msg,JsResult result){new android.app.AlertDialog.Builder(MainActivity.this).setMessage(msg).setPositiveButton("Aceptar",(d,w)->result.confirm()).setNegativeButton("Cancelar",(d,w)->result.cancel()).setOnCancelListener(d->result.cancel()).show();return true;}
 @Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams params){if(chooser!=null)chooser.onReceiveValue(null);chooser=cb;try{startActivityForResult(params.createIntent(),10);}catch(Exception e){chooser.onReceiveValue(null);chooser=null;}return true;}
 });web.addJavascriptInterface(new Object(){@JavascriptInterface public void queuePrintChat(String message){pendingPrintMessage=message;}@JavascriptInterface public void savePDF(String b64){if(b64.length()>30000000)return;pendingPDF=android.util.Base64.decode(b64,android.util.Base64.DEFAULT);runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/pdf");i.putExtra(Intent.EXTRA_TITLE,"mi-caratula.pdf");startActivityForResult(i,12);});}@JavascriptInterface public void print(){runOnUiThread(()->{PrintManager pm=(PrintManager)getSystemService(PRINT_SERVICE);pm.print("Mi Carátula",web.createPrintDocumentAdapter("Mi Carátula"),new PrintAttributes.Builder().setMediaSize(PrintAttributes.MediaSize.ISO_A4).setMinMargins(PrintAttributes.Margins.NO_MARGINS).build());});}@JavascriptInterface public void saveBackup(String json){if(json.length()>8000000)return;pendingBackup=json;runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"mi-caratula-borrador.json");startActivityForResult(i,11);});}},"AndroidPrint");web.loadUrl("file:///android_asset/index.html");}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==12&&result==RESULT_OK&&data!=null&&data.getData()!=null&&pendingPDF!=null){try(OutputStream out=getContentResolver().openOutputStream(data.getData())){out.write(pendingPDF);Toast.makeText(this,"PDF guardado",Toast.LENGTH_SHORT).show();if(pendingPrintMessage!=null){Intent chat=new Intent(Intent.ACTION_VIEW,Uri.parse("https://wa.me/51952628844?text="+Uri.encode(pendingPrintMessage)));try{startActivity(chat);}catch(Exception ignored){Toast.makeText(this,"Abre WhatsApp y envía el PDF al 952628844",Toast.LENGTH_LONG).show();}pendingPrintMessage=null;}}catch(Exception e){Toast.makeText(this,"No se pudo guardar PDF",Toast.LENGTH_LONG).show();}pendingPDF=null;}if(request==12&&result!=RESULT_OK){pendingPDF=null;pendingPrintMessage=null;}if(request==10&&chooser!=null){chooser.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(result,data));chooser=null;}if(request==11&&result==RESULT_OK&&data!=null&&data.getData()!=null&&pendingBackup!=null){try(OutputStream out=getContentResolver().openOutputStream(data.getData())){out.write(pendingBackup.getBytes(StandardCharsets.UTF_8));Toast.makeText(this,"Borrador guardado",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"No se pudo guardar el borrador",Toast.LENGTH_LONG).show();}pendingBackup=null;}}
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
}
